/**
 * AdoptionCurve — logistic adoption curve for an intervention.
 *
 * The curve is the same 0.92-ceiling logistic the Century Engine
 * uses (coverageAt in packages/core): deterministic, computed from
 * props, never from a clock or a random source.
 *
 * GENERATED by scripts/generators/components.mjs (seed 4093).
 */
import { useId } from "react";
import { cn } from "../index";

export interface AdoptionCurveProps {
  /** Year the curve switches on. */
  readonly adoptionYear: number;
  /** Logistic steepness. */
  readonly adoptionSpeed: number;
  /** Ceiling (default 0.92 — nothing reaches everyone). */
  readonly ceiling?: number;
  /** First year plotted (default: adoptionYear - 10). */
  readonly fromYear?: number;
  /** Last year plotted (default: adoptionYear + 60). */
  readonly toYear?: number;
  readonly width?: number;
  readonly height?: number;
  readonly className?: string;
}

function coverageAt(year: number, adoptionYear: number, adoptionSpeed: number, ceiling: number) {
  if (year < adoptionYear) return 0;
  const t = (year - adoptionYear) * adoptionSpeed;
  return ceiling / (1 + Math.exp(-t));
}

export function AdoptionCurve({
  adoptionYear,
  adoptionSpeed,
  ceiling = 0.92,
  fromYear,
  toYear,
  width = 320,
  height = 120,
  className,
}: AdoptionCurveProps) {
  const rawId = useId().replace(/[^a-zA-Z0-9]/g, "");
  const start = fromYear ?? adoptionYear - 10;
  const end = toYear ?? adoptionYear + 60;
  const steps = 60;
  const points: number[] = [];
  for (let i = 0; i <= steps; i++) {
    const year = start + ((end - start) * i) / steps;
    points.push(coverageAt(year, adoptionYear, adoptionSpeed, ceiling));
  }
  const pad = 6;
  const innerW = width - pad * 2;
  const innerH = height - pad * 2;
  const xAt = (i: number) => pad + (i / steps) * innerW;
  const yAt = (v: number) => pad + innerH - v * innerH;
  const path = points
    .map((v, i) => `${i === 0 ? "M" : "L"}${xAt(i).toFixed(2)},${yAt(v).toFixed(2)}`)
    .join(" ");
  const switchX = xAt(((adoptionYear - start) / (end - start)) * steps);
  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      className={cn("h-auto w-full", className)}
      role="img"
      aria-label={`adoption curve ${rawId}: speed ${adoptionSpeed}, ceiling ${ceiling}`}
    >
      <line
        x1={pad}
        x2={width - pad}
        y1={yAt(ceiling)}
        y2={yAt(ceiling)}
        className="stroke-charcoal"
        strokeDasharray="3 3"
      />
      <line
        x1={switchX}
        x2={switchX}
        y1={pad}
        y2={height - pad}
        className="stroke-charcoal"
        strokeDasharray="2 4"
      />
      <path d={path} fill="none" stroke="#2dd4bf" strokeWidth={1.5} />
    </svg>
  );
}
